// Lua script: token bucket algorithm — executed atomically via Redis EVALSHA
// Keys:   rate:{keyHash}  — Redis Hash storing bucket state
// Args:   ruleId, capacity, refillRatePerSec, nowUnixMs, cost (request cost)
// Returns: { allowed, remaining, resetUnixMs, retryAfterMs }

const tokenBucketLua = `
local bucket = redis.call('HMGET', KEYS[1], 'tokens', 'lastRefill')
local tokens = tonumber(bucket[1]) or ARGV[2]  -- start at full capacity
local lastRefill = tonumber(bucket[2]) or ARGV[3]
local now = tonumber(ARGV[3])
local capacity = tonumber(ARGV[2])
local refillRate = tonumber(ARGV[4])
local cost = tonumber(ARGV[5]) or 1

-- Refill: tokens += (now - lastRefill) * refillRate, capped at capacity
local elapsedSec = math.max(0, (now - lastRefill) / 1000)
tokens = math.min(capacity, tokens + elapsedSec * refillRate)

local allowed = 0
local remaining = tokens
local retryAfterMs = 0

if tokens >= cost then
  tokens = tokens - cost
  allowed = 1
  remaining = tokens
else
  -- deny: compute how long until one token is available
  local deficit = cost - tokens
  retryAfterMs = math.ceil((deficit / refillRate) * 1000)
end

redis.call('HMSET', KEYS[1], 'tokens', tokens, 'lastRefill', now)
redis.call('PEXPIRE', KEYS[1], math.ceil(capacity / refillRate * 1000))

local resetUnixMs = now + math.ceil((capacity - tokens) / refillRate * 1000)
return { allowed, math.floor(remaining), resetUnixMs, retryAfterMs }
`;

// ASP.NET Core middleware using Redis Lua for the hot path
public class RateLimitMiddleware
{
    public async Task InvokeAsync(HttpContext context, RequestDelegate next, RateLimitConfig config)
    {
        // Skip bypassed paths (health checks, internal service mesh)
        if (config.BypassPaths.Any(p => context.Request.Path.StartsWithSegments(p)))
        {
            await next(context);
            return;
        }

        var key = await _keyResolver.ResolveKeyAsync(context); // e.g. "user:12345"
        var rule = await _ruleStore.GetRuleForKeyAsync(key);   // cached in-memory per gateway
        if (rule == null)
        {
            await next(context); // no rule = no limit
            return;
        }

        var nowUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var result = await _redis.ExecuteLuaAsync(
            LuaScript.Prepare(tokenBucketLua),
            new RedisKey[] { string.Format("rate:{0}:{1}", rule.Id, key) },
            rule.Id, rule.BurstCapacity, nowUnixMs, rule.RefillRatePerSec, 1
        );

        var allowed = (int)result[0];
        var remaining = (int)result[1];
        var resetUnixMs = (long)result[2];
        var retryAfterMs = (int)result[3];

        context.Response.Headers["X-RateLimit-Limit"] = rule.Limit.ToString();
        context.Response.Headers["X-RateLimit-Remaining"] = remaining.ToString();
        context.Response.Headers["X-RateLimit-Reset"] = resetUnixMs.ToString();

        if (allowed == 0)
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            context.Response.Headers["Retry-After"] =
                TimeSpan.FromMilliseconds(retryAfterMs).TotalSeconds.ToString("F0");
            await _violationLogger.LogAsync(key, rule.Id, context.Request.Path);
            return;
        }

        await next(context);
    }
}
